def tri(n):
    if n < 1:
        return []
    tri_seq = [3]  # Base case for n=1
    if n >= 1:
        tri_seq.append(3)  # Base case for n=2

    for i in range(3, n + 1):
        if i % 2 == 0:
            tri_seq.append(1 + i // 2)
        else:
            tri_seq.append(tri_seq[i - 1] + tri_seq[i - 2] + tri_seq[i + 1])

    return tri_seq[:n + 1]
```

